import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { AuthProvider, useAuth } from './contexts/AuthContext';
import { TasksProvider } from './contexts/TasksContext';
import { ThemeProvider } from './contexts/ThemeContext';
import GlobalStyles from './design-system/GlobalStyles';
import LoginPage from './components/LoginPage';
import ForceChangePasswordPage from './components/ForceChangePasswordPage';
import ProtectedRoute from './components/ProtectedRoute';
import TaskManagement from './components/TaskManagement';
import CalendarPage from './components/CalendarPage';
import SettingsPage from './components/SettingsPage';
import AdminDashboard from './components/AdminDashboard';
import DashboardLayout from './components/DashboardLayout';
import { FullPageLoader } from './components/AppLoader';

const AppContent = () => {
  const { isAuthenticated, isLoading, login, user } = useAuth();

  if (isLoading) {
    return <FullPageLoader message="Preparing your workspace" />;
  }

  if (!isAuthenticated) {
    return <LoginPage onLogin={login} />;
  }

  if (user?.mustChangePassword) {
    return (
      <ForceChangePasswordPage
        onComplete={(updatedUser) => {
          login(updatedUser);
        }}
      />
    );
  }

  return (
    <ProtectedRoute>
      <Routes>
        <Route element={<DashboardLayout />}>
          <Route path="/" element={<TaskManagement />} />
          <Route path="/calendar" element={<CalendarPage />} />
          <Route path="/admin" element={<AdminDashboard />} />
          <Route path="/settings" element={<SettingsPage />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Route>
      </Routes>
    </ProtectedRoute>
  );
};

function App() {
  return (
    <ThemeProvider>
      <GlobalStyles />
      <AuthProvider>
        <TasksProvider>
          <Router>
            <AppContent />
            <Toaster
              position="top-right"
              toastOptions={{
                duration: 4000,
                style: {
                  background: 'var(--wp-surface)',
                  color: 'var(--wp-text)',
                  borderRadius: '10px',
                  boxShadow: '0 8px 24px rgba(0, 0, 0, 0.12)',
                  border: '1px solid var(--wp-border)',
                  fontSize: '14px',
                  fontWeight: 500,
                },
                success: {
                  duration: 3000,
                  iconTheme: {
                    primary: 'var(--wp-success)',
                    secondary: '#fff',
                  },
                },
                error: {
                  duration: 4000,
                  iconTheme: {
                    primary: 'var(--wp-error)',
                    secondary: '#fff',
                  },
                },
              }}
            />
          </Router>
        </TasksProvider>
      </AuthProvider>
    </ThemeProvider>
  );
}

export default App;
