import React from 'react';
import styled, { keyframes } from 'styled-components';

const spin = keyframes`
  to { transform: rotate(360deg); }
`;

const shimmer = keyframes`
  0% { background-position: -400px 0; }
  100% { background-position: 400px 0; }
`;

const Center = styled.div`
  min-height: ${(p) => p.$minHeight || '100vh'};
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: ${(p) => p.$background || 'var(--wp-bg)'};
`;

const Card = styled.div`
  width: 100%;
  max-width: 360px;
  background: var(--wp-surface);
  border: 1px solid var(--wp-border);
  border-radius: 14px;
  padding: 24px;
  text-align: center;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.08);
`;

const SpinnerShell = styled.div`
  width: ${(p) => p.$size || 36}px;
  height: ${(p) => p.$size || 36}px;
  margin: 0 auto 14px;
  border-radius: 50%;
  border: ${(p) => (p.$size && p.$size <= 20 ? 2 : 3)}px solid var(--wp-border);
  border-top-color: var(--wp-primary);
  animation: ${spin} 0.7s linear infinite;
`;

const Message = styled.p`
  margin: 0;
  color: var(--wp-text-muted);
  font-size: ${(p) => (p.$compact ? '13px' : '14px')};
  font-weight: 500;
`;

const SkeletonBlock = styled.div`
  height: ${(p) => p.$height || '12px'};
  width: ${(p) => p.$width || '100%'};
  border-radius: 6px;
  background: linear-gradient(90deg, var(--wp-surface-2) 0%, var(--wp-border) 50%, var(--wp-surface-2) 100%);
  background-size: 800px 100%;
  animation: ${shimmer} 1.4s ease-in-out infinite;
  margin-bottom: ${(p) => p.$mb || '0'};
`;

const SkeletonGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 12px;
  width: 100%;
  max-width: 900px;
`;

const SkeletonColumn = styled.div`
  background: var(--wp-surface);
  border: 1px solid var(--wp-border);
  border-radius: 10px;
  padding: 12px;
  min-height: 280px;
`;

export function FullPageLoader({ message = 'Loading workspace' }) {
  return (
    <Center>
      <Card>
        <SpinnerShell />
        <Message>{message}</Message>
      </Card>
    </Center>
  );
}

export function SectionLoader({ message = 'Loading data', minHeight = '280px' }) {
  return (
    <Center $minHeight={minHeight} $background="transparent">
      <SkeletonGrid role="status" aria-label={message}>
        {[1, 2, 3].map((col) => (
          <SkeletonColumn key={col}>
            <SkeletonBlock $height="14px" $width="60%" $mb="16px" />
            <SkeletonBlock $height="72px" $mb="8px" />
            <SkeletonBlock $height="72px" $mb="8px" />
            <SkeletonBlock $height="72px" />
          </SkeletonColumn>
        ))}
      </SkeletonGrid>
      <span className="sr-only">{message}</span>
    </Center>
  );
}

export function InlineLoader({ message = 'Loading' }) {
  return (
    <div style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }} role="status">
      <SpinnerShell $size={16} style={{ margin: 0 }} />
      <Message $compact>{message}</Message>
    </div>
  );
}

export function SkeletonCard({ height = 80 }) {
  return <SkeletonBlock $height={`${height}px`} />;
}
