import React, { useState } from 'react';
import styled from 'styled-components';
import { useForm } from 'react-hook-form';
import { authAPI } from '../services/api';
import { toast } from 'react-hot-toast';
import { InlineLoader } from './AppLoader';
import ThemeToggle from './ThemeToggle';

const Container = styled.div`
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--wp-bg);
  padding: 24px;
  position: relative;
`;

const TopBar = styled.div`
  position: absolute;
  top: 16px;
  right: 16px;
`;

const Card = styled.div`
  background: var(--wp-surface);
  border-radius: 16px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.08);
  padding: 40px;
  width: 100%;
  max-width: 400px;
  border: 1px solid var(--wp-border);
`;

const LogoMark = styled.div`
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: linear-gradient(135deg, #3b82f6, #6366f1);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 16px;
  margin-bottom: 20px;
`;

const Logo = styled.div`
  margin-bottom: 28px;

  h1 {
    font-size: 22px;
    font-weight: 700;
    color: var(--wp-text);
    margin: 0 0 6px 0;
    letter-spacing: -0.3px;
  }

  p {
    color: var(--wp-text-muted);
    font-size: 14px;
    margin: 0;
  }
`;

const Form = styled.form`
  display: flex;
  flex-direction: column;
  gap: 18px;
`;

const FormGroup = styled.div`
  display: flex;
  flex-direction: column;
  gap: 6px;
`;

const Label = styled.label`
  font-weight: 500;
  color: var(--wp-text);
  font-size: 13px;
`;

const Input = styled.input`
  padding: 11px 14px;
  border: 1px solid var(--wp-border);
  border-radius: 8px;
  font-size: 15px;
  transition: border-color 0.15s, box-shadow 0.15s;
  background: var(--wp-surface);
  color: var(--wp-text);

  &:focus {
    outline: none;
    border-color: var(--wp-primary);
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.12);
  }

  &::placeholder {
    color: var(--wp-text-subtle);
  }

  ${(props) =>
    props.$error &&
    `
    border-color: var(--wp-error);
    &:focus { box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.12); }
  `}
`;

const ErrorMessage = styled.span`
  color: var(--wp-error);
  font-size: 12px;
`;

const Button = styled.button`
  background: var(--wp-primary);
  color: white;
  border: none;
  padding: 12px 20px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  margin-top: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;

  &:hover:not(:disabled) {
    background: var(--wp-primary-hover);
  }

  &:active:not(:disabled) {
    transform: scale(0.98);
  }

  &:disabled {
    opacity: 0.6;
    cursor: not-allowed;
  }
`;

const LoginPage = ({ onLogin }) => {
  const [isLoading, setIsLoading] = useState(false);
  const { register, handleSubmit, formState: { errors } } = useForm();

  const onSubmit = async (data) => {
    setIsLoading(true);
    try {
      const response = await authAPI.login(data);
      const { token, user } = response.data;
      localStorage.setItem('token', token);
      localStorage.setItem('user', JSON.stringify(user));
      toast.success('Welcome back!');
      onLogin(user);
    } catch (error) {
      const message = error.response?.data?.message || 'Login failed. Please try again.';
      toast.error(message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Container>
      <TopBar>
        <ThemeToggle compact />
      </TopBar>
      <Card>
        <LogoMark aria-hidden>WP</LogoMark>
        <Logo>
          <h1>Welcome back</h1>
          <p>Sign in to your WorkPilot workspace</p>
        </Logo>

        <Form onSubmit={handleSubmit(onSubmit)} noValidate>
          <FormGroup>
            <Label htmlFor="email">Email</Label>
            <Input
              id="email"
              type="email"
              autoComplete="email"
              placeholder="you@company.com"
              aria-invalid={!!errors.email}
              aria-describedby={errors.email ? 'email-error' : undefined}
              {...register('email', {
                required: 'Email is required',
                pattern: { value: /^\S+@\S+$/i, message: 'Invalid email address' },
              })}
              $error={errors.email}
            />
            {errors.email && <ErrorMessage id="email-error" role="alert">{errors.email.message}</ErrorMessage>}
          </FormGroup>

          <FormGroup>
            <Label htmlFor="password">Password</Label>
            <Input
              id="password"
              type="password"
              autoComplete="current-password"
              placeholder="Enter your password"
              aria-invalid={!!errors.password}
              aria-describedby={errors.password ? 'password-error' : undefined}
              {...register('password', { required: 'Password is required' })}
              $error={errors.password}
            />
            {errors.password && <ErrorMessage id="password-error" role="alert">{errors.password.message}</ErrorMessage>}
          </FormGroup>

          <Button type="submit" disabled={isLoading}>
            {isLoading ? <InlineLoader message="Signing in" /> : 'Sign in'}
          </Button>
        </Form>
      </Card>
    </Container>
  );
};

export default LoginPage;
