import React, { useState, useRef, useEffect } from 'react';
import { NavLink, Outlet, useNavigate, useLocation } from 'react-router-dom';
import styled from 'styled-components';
import { useAuth } from '../contexts/AuthContext';
import { CommandPalette, useCommandPalette, CommandPaletteTrigger } from './CommandPalette';
import ThemeToggle from './ThemeToggle';
import {
  LayoutDashboard,
  ListTodo,
  CalendarDays,
  Settings as SettingsIcon,
  ChevronLeft,
  ChevronRight,
  LogOut,
  Menu,
  User,
} from 'lucide-react';

const LayoutWrapper = styled.div`
  height: 100dvh;
  background: var(--wp-bg);
  display: flex;
  color: var(--wp-text);
  overflow: hidden;
`;

const Sidebar = styled.aside`
  width: ${({ $collapsed }) => ($collapsed ? '72px' : '260px')};
  height: 100dvh;
  border-right: 1px solid var(--wp-sidebar-border);
  background: var(--wp-sidebar-bg);
  padding: ${({ $collapsed }) => ($collapsed ? '16px 0' : '16px 12px')};
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow-y: auto;
  overflow-x: hidden;
  flex-shrink: 0;
  z-index: 220;
  transition: width 0.22s cubic-bezier(0.4, 0, 0.2, 1);

  @media (max-width: 1024px) {
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: 260px;
    transform: translateX(${(p) => (p.$open ? '0' : '-100%')});
    transition: transform 0.22s ease;
    box-shadow: ${(p) => (p.$open ? 'var(--wp-shadow-lg)' : 'none')};
  }
`;

const SidebarTop = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: ${({ $collapsed }) => ($collapsed ? '0 8px' : '0 4px')};
`;

const Brand = styled.div`
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  overflow: hidden;

  span {
    font-size: 15px;
    font-weight: 700;
    color: var(--wp-text);
    letter-spacing: -0.3px;
    white-space: nowrap;
    opacity: ${({ $collapsed }) => ($collapsed ? 0 : 1)};
    width: ${({ $collapsed }) => ($collapsed ? 0 : 'auto')};
    transition: opacity 0.2s;
  }
`;

const BrandLogo = styled.div`
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--wp-primary), #6366f1);
  color: var(--wp-on-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 13px;
  flex-shrink: 0;
`;

const IconButton = styled.button`
  width: 28px;
  height: 28px;
  border-radius: 6px;
  border: 1px solid var(--wp-border);
  background: var(--wp-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--wp-text-muted);
  flex-shrink: 0;

  &:hover {
    background: var(--wp-surface-2);
    color: var(--wp-text);
  }
`;

const Navigation = styled.nav`
  display: flex;
  flex-direction: column;
  gap: 2px;
`;

const StyledNavLink = styled(NavLink)`
  display: flex;
  align-items: center;
  gap: 10px;
  padding: ${({ $collapsed }) => ($collapsed ? '10px' : '9px 12px')};
  justify-content: ${({ $collapsed }) => ($collapsed ? 'center' : 'flex-start')};
  border-radius: 8px;
  font-weight: 500;
  font-size: 14px;
  color: var(--wp-text-muted);
  text-decoration: none;
  transition: background 0.15s, color 0.15s;

  &.active {
    color: var(--wp-primary);
    background: var(--wp-primary-muted);
    font-weight: 600;
  }

  &:hover:not(.active) {
    background: var(--wp-hover);
    color: var(--wp-text);
  }

  .nav-label {
    ${({ $collapsed }) =>
      $collapsed
        ? 'position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0);'
        : ''}
  }
`;

const SidebarFooter = styled.div`
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--wp-border);
  display: flex;
  flex-direction: column;
  gap: 8px;
`;

const UserMenuWrap = styled.div`
  position: relative;
`;

const UserButton = styled.button`
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: ${({ $collapsed }) => ($collapsed ? '8px' : '8px 10px')};
  justify-content: ${({ $collapsed }) => ($collapsed ? 'center' : 'flex-start')};
  border: 1px solid var(--wp-border);
  border-radius: 8px;
  background: var(--wp-surface);
  cursor: pointer;
  text-align: left;
  color: var(--wp-text);

  &:hover {
    background: var(--wp-surface-2);
  }
`;

const UserAvatar = styled.div`
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--wp-primary), #8b5cf6);
  color: var(--wp-on-primary);
  font-size: 11px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
`;

const UserInfo = styled.div`
  flex: 1;
  min-width: 0;
  display: ${({ $collapsed }) => ($collapsed ? 'none' : 'block')};

  .name {
    font-size: 13px;
    font-weight: 600;
    color: var(--wp-text);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .email {
    font-size: 11px;
    color: var(--wp-text-subtle);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
`;

const Dropdown = styled.div`
  position: absolute;
  bottom: calc(100% + 6px);
  left: 0;
  right: 0;
  background: var(--wp-surface-elevated);
  border: 1px solid var(--wp-border);
  border-radius: 10px;
  box-shadow: var(--wp-shadow-lg);
  padding: 6px;
  z-index: 300;
`;

const DropdownItem = styled.button`
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border: none;
  border-radius: 6px;
  background: transparent;
  font-size: 13px;
  font-weight: 500;
  color: var(--wp-text);
  cursor: pointer;
  text-align: left;

  &:hover {
    background: var(--wp-hover);
  }

  &.danger {
    color: var(--wp-error);
  }
`;

const ContentArea = styled.main`
  flex: 1;
  height: 100dvh;
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
`;

const TopHeader = styled.header`
  display: none;
  height: 52px;
  padding: 0 20px;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--wp-border);
  background: var(--wp-header-bg);
  backdrop-filter: blur(12px);
  flex-shrink: 0;
  z-index: 100;

  @media (min-width: 1025px) {
    display: flex;
  }
`;

const TopHeaderTitle = styled.h1`
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--wp-text);
  letter-spacing: -0.2px;
`;

const TopHeaderActions = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
`;

const MobileHeader = styled.header`
  display: none;
  height: 52px;
  padding: 0 16px;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--wp-border);
  background: var(--wp-header-bg);
  backdrop-filter: blur(12px);
  flex-shrink: 0;

  @media (max-width: 1024px) {
    display: flex;
  }
`;

const MobileHeaderActions = styled.div`
  display: flex;
  align-items: center;
  gap: 6px;
`;

const PageScroll = styled.div`
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--wp-bg);
`;

const SidebarOverlay = styled.button`
  display: none;
  position: fixed;
  inset: 0;
  border: none;
  background: var(--wp-overlay);
  z-index: 200;
  padding: 0;
  cursor: default;

  @media (max-width: 1024px) {
    display: ${(p) => (p.$show ? 'block' : 'none')};
  }
`;

const SkipLink = styled.a`
  position: absolute;
  left: -9999px;
  top: 8px;
  z-index: 9999;
  padding: 8px 16px;
  background: var(--wp-primary);
  color: var(--wp-on-primary);
  border-radius: 6px;
  font-weight: 600;
  text-decoration: none;

  &:focus {
    left: 8px;
  }
`;

const PAGE_TITLES = {
  '/': 'Tasks',
  '/calendar': 'Calendar',
  '/admin': 'Dashboard',
  '/settings': 'Settings',
};

function getInitials(user) {
  const name = user?.fullName || user?.email || '?';
  const parts = name.trim().split(/\s+/);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return name.slice(0, 2).toUpperCase();
}

const DashboardLayout = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const userMenuRef = useRef(null);
  const palette = useCommandPalette();

  const closeSidebar = () => setIsSidebarOpen(false);
  const isAdmin = user?.roles?.includes('admin');
  const canOpenSettings = isAdmin || user?.permissions?.includes('kanban.manage');
  const pageTitle = PAGE_TITLES[location.pathname] || 'WorkPilot';

  useEffect(() => {
    const onClickOutside = (e) => {
      if (userMenuRef.current && !userMenuRef.current.contains(e.target)) {
        setUserMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', onClickOutside);
    return () => document.removeEventListener('mousedown', onClickOutside);
  }, []);

  const handleCreateTask = () => {
    palette.close();
    navigate('/', { state: { openCreateTask: true } });
  };

  return (
    <LayoutWrapper>
      <SkipLink href="#main-content">Skip to main content</SkipLink>
      <SidebarOverlay $show={isSidebarOpen} onClick={closeSidebar} aria-label="Close navigation" />
      <Sidebar $open={isSidebarOpen} $collapsed={isCollapsed}>
        <SidebarTop $collapsed={isCollapsed}>
          <Brand $collapsed={isCollapsed}>
            <BrandLogo>WP</BrandLogo>
            <span>WorkPilot</span>
          </Brand>
          <IconButton
            type="button"
            onClick={() => setIsCollapsed((p) => !p)}
            aria-label={isCollapsed ? 'Expand sidebar' : 'Collapse sidebar'}
          >
            {isCollapsed ? <ChevronRight size={14} /> : <ChevronLeft size={14} />}
          </IconButton>
        </SidebarTop>

        <CommandPaletteTrigger
          collapsed={isCollapsed}
          onClick={() => palette.setOpen(true)}
        />

        <Navigation aria-label="Main navigation">
          <StyledNavLink to="/" end $collapsed={isCollapsed} onClick={closeSidebar}>
            <ListTodo size={18} aria-hidden />
            <span className="nav-label">Tasks</span>
          </StyledNavLink>
          <StyledNavLink to="/calendar" $collapsed={isCollapsed} onClick={closeSidebar}>
            <CalendarDays size={18} aria-hidden />
            <span className="nav-label">Calendar</span>
          </StyledNavLink>
          {isAdmin && (
            <StyledNavLink to="/admin" $collapsed={isCollapsed} onClick={closeSidebar}>
              <LayoutDashboard size={18} aria-hidden />
              <span className="nav-label">Dashboard</span>
            </StyledNavLink>
          )}
          {canOpenSettings && (
            <StyledNavLink to="/settings" $collapsed={isCollapsed} onClick={closeSidebar}>
              <SettingsIcon size={18} aria-hidden />
              <span className="nav-label">Settings</span>
            </StyledNavLink>
          )}
        </Navigation>

        <SidebarFooter>
          <UserMenuWrap ref={userMenuRef}>
            {userMenuOpen && !isCollapsed && (
              <Dropdown role="menu">
                <DropdownItem type="button" role="menuitem" className="danger" onClick={logout}>
                  <LogOut size={16} />
                  Sign out
                </DropdownItem>
              </Dropdown>
            )}
            <UserButton
              type="button"
              $collapsed={isCollapsed}
              onClick={() => {
                if (isCollapsed) setIsCollapsed(false);
                setUserMenuOpen((p) => !p);
              }}
              aria-expanded={userMenuOpen}
              aria-haspopup="menu"
            >
              <UserAvatar>{getInitials(user)}</UserAvatar>
              <UserInfo $collapsed={isCollapsed}>
                <div className="name">{user?.fullName || 'User'}</div>
                <div className="email">{user?.email}</div>
              </UserInfo>
              {!isCollapsed && <User size={14} color="var(--wp-text-subtle)" />}
            </UserButton>
          </UserMenuWrap>
          {isCollapsed && (
            <IconButton type="button" onClick={logout} aria-label="Sign out" title="Sign out">
              <LogOut size={14} />
            </IconButton>
          )}
        </SidebarFooter>
      </Sidebar>

      <ContentArea>
        <TopHeader>
          <TopHeaderTitle>{pageTitle}</TopHeaderTitle>
          <TopHeaderActions>
            <ThemeToggle />
          </TopHeaderActions>
        </TopHeader>

        <MobileHeader>
          <Brand $collapsed={false}>
            <BrandLogo>WP</BrandLogo>
            <span>{pageTitle}</span>
          </Brand>
          <MobileHeaderActions>
            <ThemeToggle compact />
            <IconButton type="button" onClick={() => setIsSidebarOpen((p) => !p)} aria-label="Open menu">
              <Menu size={18} />
            </IconButton>
          </MobileHeaderActions>
        </MobileHeader>

        <PageScroll id="main-content" tabIndex={-1}>
          <Outlet />
        </PageScroll>
      </ContentArea>

      <CommandPalette
        open={palette.open}
        onClose={palette.close}
        onCreateTask={handleCreateTask}
      />
    </LayoutWrapper>
  );
};

export default DashboardLayout;
